                            ? "ring-4 ring-[#e8872d]"
                            : ""
                        }`}
                        style={{
                          left: `${point.position.x}%`,
                          top: `${point.position.y}%`,
                          backgroundColor: getPathPointColour(point),
                        }}
                        title={
                          isPointZ(point)
                            ? `${participant.name}: Point Z is locked to the primary collision marker`
