                      }}
                      title={`${participant.name} — ${state.speedKmh.toFixed(0)} km/h`}
                    >
                      <ParticipantShape
                        participant={participant}
                        selected={selectedParticipantId === participant.id}
                      />
                    </button>
                  </div>
                );
              })}
            </div>
            </div>

          </main>



        </div>

        {activeReconstructionView === "2D" &&
          workspaceRightPanelHost &&
          createPortal(
