                                    {
                                      tracePoints: [],
                                    },
                                  )
                                }
                              />
                            </div>
                          </details>
                        ) : !selectedParticipant ||
                          !selectedParticipantState ? (
                          <div className="reconstruction-workspace__blender-properties-empty">
