                                  <span>Name</span>
                                  <input
                                    value={selectedParticipant.name}
                                    onChange={(event) =>
                                      updateParticipant(
                                        selectedParticipant.id,
                                        {
                                          name:
                                            event.target.value,
                                        },
                                      )
                                    }
                                  />
                                </label>

                                <label>
                                  <span>Type</span>
                                  <select
