    effectiveShowObjects,
    effectiveShowPaths,
    effectiveShowPhysics,
    reconstruction,
    workspaceMode,
    workspaceTimeSourceRef,
    workspaceTool,
  ]);

  const setTime = (value: number) => {
    const next = clamp(value, 0, reconstruction.durationSeconds);
    timeRef.current = next;
    setDisplayTime(next);
  };

  const handlePlayPause = () => {
